 const acquisitionKnowledge={
  uriel:{quest:'The Old Peace',parts:['Uriel Chassis Blueprint','Uriel Neuroptics Blueprint','Uriel Systems Blueprint'],recipe:[['Agnovidisc',1975],['Laudavi',880],['Servoris',350],['Orokin Cell',1]],currency:'Maphica',vendor:'Roathe — La Cathédrale, Sanctum Anatomica',partCost:25,mainCost:75,url:'https://wiki.warframe.com/w/Uriel'}
 };
 const activityKnowledge=[
  {match:/the descendia: roathe/i,location:'Roathe’s Oblivion — The Descendia, Infernum 21',quest:'The Old Peace',detail:'Clear Descendia to Infernum 21 once; thereafter repeat the final boss checkpoint directly. The repeatable part reward is separate from weekly rewards.'},
  {match:/the descendia:/i,location:null,quest:'The Old Peace',detail:'Enter via La Cathédrale in Sanctum Anatomica. Check weekly reward eligibility and Normal versus Steel Path.'}
 ];
 function parentParts(query,index){
  const suffix=/^(blueprint|(?:chassis|neuroptics|systems|barrel|receiver|stock|handle|blade|hilt|grip|link|string|limb|ornament|gauntlet|carapace|engine|pod|disc|head|body|wings)(?: blueprint)?)$/i;
  return [...index].filter(([k])=>k.startsWith(query+' ')&&suffix.test(k.slice(query.length+1))).map(([,v])=>v.name);
 }
 function planKnowledge(query,equipment,g,steps,info){
  const entry=acquisitionKnowledge[query];if(!entry)return;
  const p=equipment?personalEquipment(equipment)||{}:Object.values(state.profile?.equipment||{}).find(x=>itemKey(x.name)===query)||{};
  const held=part=>Object.entries(p.parts||{}).some(([k,v])=>v&&itemAliases(k).some(a=>itemAliases(part).includes(a)||itemAliases(part.slice(query.length+1)).includes(a)));
  const missing=entry.parts.filter(part=>!held(part)),status=g.quests?.[entry.quest];
  if(status!=='completed')steps.push(step('Unlock '+entry.quest,'Complete the quest first if not yet done. Recorded status: '+(status||'unknown')+'. The quest awards the main blueprint.',source(entry.url,'Wiki')));
  else steps.push(step('Main blueprint — quest reward','The Old Peace is recorded complete. Check your Foundry/inbox before spending Maphica.',source(entry.url,'Wiki')));
  if(missing.length)steps.push(step('Farm missing components together — Infernum 21','Each component has a 12.5% chance per repeatable boss reward. Clear to the checkpoint once, then repeat Roathe directly. Missing/not confirmed: '+missing.join(', ')+'.',source('https://wiki.warframe.com/w/Descendia','Wiki')));
  const cost=missing.length*entry.partCost;
  if(cost)steps.push(step('Buy remaining blueprints — '+entry.vendor,'25 Maphica per missing component; '+cost+' Maphica for the '+missing.length+' not confirmed held. Main blueprint costs 75 only if needed. Check your balance; stop boss farming when you can afford the remaining parts.',source(entry.url,'Wiki')));
  steps.push(step('Farm crafting ingredients — The Perita Rebellion',entry.recipe.map(([n,q])=>q.toLocaleString()+' '+n).join(' · ')+'. Full-set totals before subtracting existing stock; Orokin Cell is a separate regional resource. Check Foundry stock.',source(entry.url,'Wiki')));
  info.push('Verified acquisition and crafting guidance: '+source(entry.url,'Warframe Wiki')+' · '+source('https://www.warframe.com/en/patch-notes/psn/41-0-0','Official PlayStation update notes'));
 }


