   if(boss)steps.push(step(boss[0]+' — Assassination','Defeat '+boss[1]+'. Repeat until the required component reward(s) are obtained; check published rolls below.',source(wikiUrl,'Wiki')));
   if(route)steps.push(step(route[0],route[1],source(wikiUrl,'Wiki')));
