   if(query==='citrine')steps.push(step('Otak — Necralisk','Buy missing blueprints with the two crystal fragment types earned in Mirror Defense. Verify the cost of each component; stop farming when the outstanding purchases are affordable.',source(wikiUrl,'Wiki')));
